// 原接受行动先取同候选亲历来源，原AddLot后再绑定唯一信件；记录本身不交付内容、不花第二份钱。
#include "task_message_notice.hpp"
#include <limits>
namespace hanmo::resident { namespace {
Status services(const TaskMessageNoticeServices* s){if(!s)return common_success();if(!s->catalog||!s->state||!s->read||!s->validate||s->catalog->version!=1||s->state->version!=1)return common_failure("TaskMessageNoticeServicesMismatch");return common_success();}
Status source_matches(const CommonStore& common,const TaskDefinition& d,const TaskDeathNoticeBindingPolicy& p,const WitnessedDeathNoticeSource& source,Integer tick){if(d.issuer.kind!=Owner::Kind::actor||source.world_id!=common.state().identity.world_id||source.scenario_id!=common.state().metadata.scenario_id||source.sender_actor_id!=d.issuer.id||source.recipient_actor_id!=d.goal.receiver_actor||source.decedent_actor_id!=p.decedent_actor_id||source.issued_tick!=tick)return common_failure("TaskMessageNoticeSourceMismatch");return common_success();}
}
Status preview_task_message_notice_acceptance(const CommonStore& common,const TaskState&,const TaskCatalog& catalog,const CommonCatalog& shared,const TaskMessageNoticeServices* s,const StableId& offer){auto valid=services(s);if(!valid.ok||!s)return valid;valid=validate_task_message_notice_catalog(*s->catalog,catalog,shared);if(!valid.ok)return valid;const auto* policy=s->catalog->bindings.find(offer);if(!policy)return common_success();const auto* d=catalog.offers.find(offer);auto source=s->read(d->issuer.id,d->goal.receiver_actor,policy->decedent_actor_id,common.tick(),nullptr);if(!source.ok)return {false,{},source.error};return source_matches(common,*d,*policy,source.value,common.tick());}
Outcome<std::optional<TaskMessageNoticePreparation>> prepare_task_message_notice_acceptance(const CommonStore& common,const TaskState& tasks,const TaskCatalog& catalog,const CommonCatalog& shared,const TaskMessageNoticeServices* s,const ActionCoreView& action,Integer tick){
    auto valid=services(s);if(!valid.ok)return {false,{},valid.error};if(!s||action.kind!="accept_offer")return {true,std::nullopt,{}};const auto* params=tasks.actions.find(action.id);const auto* task=params?tasks.tasks.find(params->task_id):nullptr;const auto* policy=task?s->catalog->bindings.find(task->offer_id):nullptr;if(!policy)return {true,std::nullopt,{}};valid=validate_task_message_notice_catalog(*s->catalog,catalog,shared);if(!valid.ok)return {false,{},valid.error};
    const auto fail=[](const StableId& code)->Outcome<std::optional<TaskMessageNoticePreparation>>{return {false,{},common_failure(code).error};};
    const auto* d=catalog.offers.find(task->offer_id);const auto* live=common.action(action.id);const auto* carrier=common.actor(action.actor_id);const auto* sender=common.actor(d->issuer.id);const auto* role=shared.roles.find(params->context.role_id);const auto* assignment=common.state().roles.find(params->context.role_id);
    if(task->contract_id||task->status!="accepting"||task->assignee!=action.actor_id||params->offer_id!=d->id||!live||live->kind!=action.kind||live->actor_id!=action.actor_id||!carrier||!sender||!carrier->alive||!sender->alive||!carrier->available||!sender->available||carrier->action_id!=action.id||sender->action_id!=action.id||params->context.provider_actor_id!=sender->id||params->context.role_id!=d->accept_role||!role||!assignment||!assignment->enabled||assignment->actor_id!=sender->id||role->place_id!=params->context.place_id||std::find(role->services.begin(),role->services.end(),"accept_offer")==role->services.end()||std::find(live->participants.begin(),live->participants.end(),carrier->id)==live->participants.end()||std::find(live->participants.begin(),live->participants.end(),sender->id)==live->participants.end())return fail("InvalidTaskMessageNoticeAcceptance");
    if(!s->phase||s->phase->from_tick!=common.tick()||common.tick()<0||common.tick()==std::numeric_limits<Integer>::max()||s->phase->to_tick!=common.tick()+1||tick!=s->phase->to_tick)return fail("TaskMessageNoticePhaseMismatch");
    auto a=common.resolved_location(carrier->id),b=common.resolved_location(sender->id);const auto* from=a.ok?std::get_if<SettlementLocation>(&a.value):nullptr;const auto* to=b.ok?std::get_if<SettlementLocation>(&b.value):nullptr;if(!from||!to||from->place_id!=params->context.place_id||to->place_id!=from->place_id||to->settlement_id!=from->settlement_id)return fail("TaskMessageNoticeSenderNotPresent");
    for(const auto& row:s->state->bindings.rows())if(row.second.task_id==task->id||row.second.accept_action_id==action.id)return fail("DuplicateTaskMessageNoticeBinding");const auto* inventory=common.inventory(carrier->inventory_id);if(!inventory||!owner_equal(inventory->owner,Owner{Owner::Kind::actor,carrier->id,{}}))return fail("TaskMessageNoticeCustodyMismatch");
    auto source=s->read(sender->id,d->goal.receiver_actor,policy->decedent_actor_id,tick,s->phase);if(!source.ok)return {false,{},source.error};valid=source_matches(common,*d,*policy,source.value,tick);if(!valid.ok)return {false,{},valid.error};
    TaskMessageNoticePreparation prepared;prepared.item_id=d->goal.message_id;for(const auto& lot:inventory->lots){if(owner_equal(lot.owner,Owner{Owner::Kind::task,task->id,{}}))return fail("TaskMessageNoticeLetterAlreadyExists");prepared.previous_lot_ids.push_back(lot.id);}auto& binding=prepared.binding;binding.task_id=task->id;binding.offer_id=d->id;binding.accept_action_id=action.id;binding.carrier_actor_id=carrier->id;binding.carrier_inventory_id=inventory->id;binding.tick=tick;binding.source=std::move(source.value);return {true,std::move(prepared),{}};
}
Status record_task_message_notice_after_resources(CommonStore& common,TaskMessageNoticeState& state,const TaskMessageNoticePreparation& prepared){const auto& b=prepared.binding;if(state.version!=1||!b.fact_id.empty()||!b.source_lot_id.empty())return common_failure("InvalidTaskMessageNoticePreparation");for(const auto& row:state.bindings.rows())if(row.second.task_id==b.task_id||row.second.accept_action_id==b.accept_action_id)return common_failure("DuplicateTaskMessageNoticeBinding");const auto* inventory=common.inventory(b.carrier_inventory_id);if(!inventory||!owner_equal(inventory->owner,Owner{Owner::Kind::actor,b.carrier_actor_id,{}}))return common_failure("TaskMessageNoticeCustodyMismatch");StableId letter;for(const auto& lot:inventory->lots)if(owner_equal(lot.owner,Owner{Owner::Kind::task,b.task_id,{}})){if(!letter.empty()||lot.item_id!=prepared.item_id||lot.quantity!=1||!lot.reserved_by.empty()||std::find(prepared.previous_lot_ids.begin(),prepared.previous_lot_ids.end(),lot.id)!=prepared.previous_lot_ids.end())return common_failure("TaskMessageNoticeLetterMismatch");letter=lot.id;}if(letter.empty())return common_failure("TaskMessageNoticeLetterMissing");auto id=common.next_id("task_death_notice_bound");if(!id.ok)return {false,{},id.error};auto binding=b;binding.fact_id=id.value;binding.source_lot_id=std::move(letter);auto result=common.append_fact({id.value,task_death_notice_bound_kind,"tasks"});if(!result.ok)return result;if(!state.bindings.insert(id.value,std::move(binding)))return common_failure("DuplicateTaskMessageNoticeBinding");state.task_to_binding[b.task_id]=id.value;return common_success();}
}
